// Polices web-safe usuelles (Arial/Times New Roman/Courier New/Georgia/Calibri),
// embarquees via des equivalents libres a metrique IDENTIQUE (memes largeurs de
// caracteres donc meme mise en page - formes de lettres legerement differentes) :
// pdfmake ne peut jamais utiliser une police du systeme (contrairement au
// navigateur) - Arial/Times New Roman/Calibri sont des polices commerciales dont
// les fichiers ne peuvent pas etre distribues ici. Correspondance retenue (meme
// principe que LibreOffice/Google Docs) :
//   Arial            -> Arimo   (Google Fonts, licence OFL)
//   Times New Roman  -> Tinos   (Google Fonts, licence OFL)
//   Courier New      -> Cousine (Google Fonts, licence OFL)
//   Georgia          -> Gelasio (Google Fonts, licence OFL)
//   Calibri          -> Carlito (Google Fonts, licence OFL)
// Fichiers regular/bold/italic/bolditalic sources : github.com/google/fonts
// (Arimo/Gelasio instancies en statique depuis leur police variable via
// fonttools varLib.instancer - pdfmake ne sait pas lire une police variable),
// sous-ensemble latin + latin-ext + ponctuation courante (memes caracteres que
// Roboto, cf. pdf-fonts.js) pour limiter le poids embarque.
(function () {
  if (!window.pdfMake || !window.pdfMake.vfs) return;
  if (!window.pdfMake.fonts) window.pdfMake.fonts = {};

  window.pdfMake.vfs['Arimo-Regular.ttf'] = '';
  window.pdfMake.vfs['Arimo-Bold.ttf'] = '';
  window.pdfMake.vfs['Arimo-Italic.ttf'] = '';
  window.pdfMake.vfs['Arimo-BoldItalic.ttf'] = '';
  window.pdfMake.fonts.Arimo = { normal: 'Arimo-Regular.ttf', bold: 'Arimo-Bold.ttf', italics: 'Arimo-Italic.ttf', bolditalics: 'Arimo-BoldItalic.ttf' };

  window.pdfMake.vfs['Tinos-Regular.ttf'] = '';
  window.pdfMake.vfs['Tinos-Bold.ttf'] = '';
  window.pdfMake.vfs['Tinos-Italic.ttf'] = '';
  window.pdfMake.vfs['Tinos-BoldItalic.ttf'] = '';
  window.pdfMake.fonts.Tinos = { normal: 'Tinos-Regular.ttf', bold: 'Tinos-Bold.ttf', italics: 'Tinos-Italic.ttf', bolditalics: 'Tinos-BoldItalic.ttf' };

  window.pdfMake.vfs['Cousine-Regular.ttf'] = '';
  window.pdfMake.vfs['Cousine-Bold.ttf'] = '';
  window.pdfMake.vfs['Cousine-Italic.ttf'] = '';
  window.pdfMake.vfs['Cousine-BoldItalic.ttf'] = '';
  window.pdfMake.fonts.Cousine = { normal: 'Cousine-Regular.ttf', bold: 'Cousine-Bold.ttf', italics: 'Cousine-Italic.ttf', bolditalics: 'Cousine-BoldItalic.ttf' };

  window.pdfMake.vfs['Gelasio-Regular.ttf'] = '';
  window.pdfMake.vfs['Gelasio-Bold.ttf'] = '';
  window.pdfMake.vfs['Gelasio-Italic.ttf'] = '';
  window.pdfMake.vfs['Gelasio-BoldItalic.ttf'] = '';
  window.pdfMake.fonts.Gelasio = { normal: 'Gelasio-Regular.ttf', bold: 'Gelasio-Bold.ttf', italics: 'Gelasio-Italic.ttf', bolditalics: 'Gelasio-BoldItalic.ttf' };

  window.pdfMake.vfs['Carlito-Regular.ttf'] = '';
  window.pdfMake.vfs['Carlito-Bold.ttf'] = '';
  window.pdfMake.vfs['Carlito-Italic.ttf'] = '';
  window.pdfMake.vfs['Carlito-BoldItalic.ttf'] = '';
  window.pdfMake.fonts.Carlito = { normal: 'Carlito-Regular.ttf', bold: 'Carlito-Bold.ttf', italics: 'Carlito-Italic.ttf', bolditalics: 'Carlito-BoldItalic.ttf' };

})();
